static void FlecsGeneratedBody_Event_enum_event_803d3ccc() {
	struct Event {};
 
 
    struct Data {
        Type type;
        int value;
    };


    struct {
        size_t _any = 0u;
        size_t type_a = 0u;
        size_t type_b = 0u;
        size_t data = 0u;
        size_t data_type_a = 0u;
        size_t data_type_b = 0u;
    } observed;

    flecs::world ecs;
	RegisterFlecsGeneratedTestTypes_05aca79120(ecs);

    ecs.component<Event>();
    ecs.component<Type>();
    ecs.component<Data>();

    ecs.observer()
        .with(flecs::Wildcard)
        .event<Event>()
        .each([&](flecs::entity) {
            ++observed._any;
        });

    ecs.observer()
        .with(Type::A)
        .event<Event>()
        .each([&](flecs::entity) {
            ++observed.type_a;
        });

    ecs.observer()
        .with(Type::B)
        .event<Event>()
        .each([&](flecs::entity) {
            ++observed.type_b;
        });

    ecs.observer<Data>()
        .event<Event>()
        .each([&](flecs::entity, Data data) {
            ++observed.data;
            test_assert(data.value >= 1 && data.value <= 2);
        });
 
 
    ecs.observer<Data>()
        .with(Type::A)
        .event<Event>()
        .each([&](flecs::entity, Data data) {
            ++observed.data_type_a;
            test_int(data.value, 1);
        });

    ecs.observer<Data>()
        .with(Type::B)
        .event<Event>()
        .each([&](flecs::entity, Data data) {
            ++observed.data_type_b;
            test_int(data.value, 2);
        });

    {
        auto event1 = ecs.entity()
            .add(Type::A)
            .emplace<Data>(Type::A, 1);

        ecs.event<Event>()
            .id(Type::A)
            .id<Data>()
            .entity(event1).emit();
    }

    {
        auto event2 = ecs.entity()
            .add(Type::B)
            .emplace<Data>(Type::B, 2);

        ecs.event<Event>()
            .id(Type::B)
            .id<Data>()
            .entity(event2).emit();
    }

    test_int(observed._any, 2u);
    test_int(observed.type_a, 1u);
    test_int(observed.type_b, 1u);
    test_int(observed.data_type_a, 1u);
    test_int(observed.data_type_b, 1u);
}

